/// Read a port from a small configuration file.
pub fn parse_port(input: &str) -> u16 {
    input.trim().parse::<u16>().unwrap()
}

before.src/main.rs:
use port_parser::parse_port;

fn main() {
    let port = parse_port("8080");
    println!("Listening on port {port}");
}

